export type ReturnedIdentityResult = {
    readonly status: "applied";
} | {
    readonly status: "not_applied";
    readonly reason: "negative_confirmation";
} | {
    readonly status: "conflict";
    readonly reason: "request_binding" | "unknown_identity" | "identity_mismatch" | "follower_set" | "unconfirmed" | "malformed_response";
    readonly keys: readonly string[];
};

export interface BoundReturnedIdentitySchema {
    readonly operation: FrozenRequest["operation"];
    readonly requestDigest: string;
    readonly schema: ReturnedIdentitySchema;
}

server/highlevel/operations/returned-ide:
export interface CreatedIdentitySlot {
    readonly path: string;
    readonly role: string;
    readonly when: "always" | "new" | "missing_request_id";
}

export interface ApprovedIdentitySource {
    readonly path: string;
    readonly role: string;
}

export interface ReturnedIdentitySchema {
    readonly operation: OperationId;
    readonly primary: string;
    readonly identities: Readonly<Record<string, string>>;
    readonly sources: readonly ApprovedIdentitySource[];
    readonly created: readonly CreatedIdentitySlot[];
    readonly passThrough: Readonly<{
        locationId: "connectedLocation";
    }>;
    readonly followers: boolean;
}

server/highlevel/approval-idempotency.ts:
export type ApprovalOutcome = {
    readonly status: "applied";
    readonly result: unknown;
} | {
    readonly status: "conflict";
    readonly reason: ApprovalConflictReason;
};

export type ApprovalIdempotencyRecord = {
    readonly approvalId: string;
    readonly requestDigest: string;
} & ({
    readonly state: "pending";
} | {
    readonly state: "applied";
    readonly result: unknown;
} | {
    readonly state: "conflict";
    readonly reason: ApprovalConflictReason;
});

export interface ApprovalJournal {
    readonly key: string;
    get(approvalId: string): ApprovalIdempotencyRecord | undefined;
    claim(approvalId: string, requestDigest: string): boolean;
    settle(approvalId: string, requestDigest: string, outcome: ApprovalOutcome): ApprovalOutcome;
}

class FileApprovalJournal   implements ApprovalJournal {
readonly key: string;
constructor(directory: string);
get(approvalId: string): ApprovalIdempotencyRecord | undefined;
claim(approvalId: string, requestDigest: string): boolean;
settle(approvalId: string, requestDigest: string, outcome: ApprovalOutcome): ApprovalOutcome;
}

export interface ApprovedWriteCallbacks {
    dispatch(): Promise<ApprovalOutcome>;
    reconcile(): Promise<ApprovalOutcome>;
}
